          "description": "Applicant must be able to read a number plate from 20 metres away",
          "condition": {
            "field": "can_read_number_plate",
            "operator": "==",
            "value": true
          },
          "reason_if_failed": "You must be able to read a number plate from 20 metres away. If you need glasses or contact lenses to do this, you can still drive.",
          "triggers_handoff": true
